local function PickCommit(src, a1, a2)
  local skill = to_u32(FocusedSkill())
  if skill == Miximax.CREATE then
    local card = CreateCard()
    if Miximax.prime or (card ~= nil and not card.create_allowed(skill, Miximax.hdl or 0)) then
      funcLuaCommand(1917805374, 2086672038 --[[sy0003]])
      return
    end
    character_reforged_free[skill] = true                      -- never equipped: always choosable
  end
  if skill == ModeChange.CREATE then
    character_reforged_free[skill] = true
  end
  local mck = ModeChangeIndex(skill)
  if mck ~= nil then
    funcLuaCommand(1917805374, 2086672038)
    return
  end
  if skill == Miximax.FUSION or (Miximax.chara ~= 0 and not MiximaxCompatible(skill)) then
    funcLuaCommand(1917805374, 2086672038 --[[sy0003]])
    return
  end
  if skill ~= 0 and Allowed(skill) and character_reforged_free[skill] == false and character_reforged_used[skill] == nil then
    PlayerSet(KEY_DEBUG_CODE, 5)
    funcLuaCommand(1917805374, 2086672038 --[[sy0003]])
    return
  end
  if skill == 0 or not Allowed(skill) then
    PlayerSet(KEY_DEBUG_CODE, 3)
    funcLuaCommand(1917805374, 2086672038 --[[sy0003]])
    return
  end
  PlayerSet(KEY_RESULT, skill)
  PlayerSet(KEY_INV, character_reforged_inv[skill] or 0)
  PlayerSet(KEY_DEBUG_CODE, 4)
  funcLuaCommand(1917805374, 4235359837 --[[sy0010]])
  if ListState.RetailOnBack ~= nil then
    pcall(ListState.RetailOnBack)        -- the retail back: saves the shown tab's filter
  end
  character_reforged_pick = false
  funcLuaCommand(320421347, 2897322950 --[[ability_list_menu]])
end

-- Keyboard and pad confirm arrives as OnEnter(list layer).
local function Mark(bit)
  if character_reforged_pick and character_reforged_bits % (bit * 2) < bit then
    character_reforged_bits = character_reforged_bits + bit
    PlayerSet(KEY_DEBUG_BITS, character_reforged_bits)
  end
end

local function PickEntry(src, a1, a2)
  if character_reforged_pick then
    PlayerSet(KEY_DEBUG_ENTER, to_u32(a1))
    Mark(src == "OnEnter" and Bit.ONENTER or src == "OnDecideFocus" and Bit.ONDECIDE or Bit.COMMIT)
  end
  if not character_reforged_pick or (a1 ~= List and a1 ~= Item) then
    return
  end
  -- a popup of the picker is open (or its closing press is still down), or a confirm already ran this frame
  if ListState.quiet() or ListState.decided_frame == ListState.frame then
    return
  end
  ListState.decided_frame = ListState.frame
  if src == "OnDecideFocus" and a1 == Item then
    ListState.focus_row_skill(a2)
  end
  local ok, err = pcall(PickCommit, src, a1, a2)
  if not ok then
    PRINT("ability_list_menu EVT pick: " .. tostring(err))
    PlayerSet(KEY_DEBUG_CODE, 9)
    funcLuaCommand(1917805374, 2086672038 --[[sy0003]])
  end
end

