-- Returns a menu_text row (text\rows\skill_table.toml of this mod) with its <TAG>s filled from `values`.
function ListState.text(id, values)
  local ok, s = pcall(funcLuaCommand, 4074371074, id)
  if not ok or type(s) ~= "string" then
    return ""
  end
  for tag, v in pairs(values or {}) do
    local text = tostring(v)
    s = string.gsub(s, "<" .. tag .. ">", function()
      return text
    end)
  end
  return s
end
