-- Card layers are hidden (their wanted visibility remembered) and the first Step after the list opened shows them.
local DetailWait = {
  LAYERS = {2628045944 --[[team02_02_skill_detail_info]], 2651268807 --[[team00_30_aura_keshin_detail_info]],
    395833588 --[[team00_30_aura_keshin_armed_detail_info]], 3679282495 --[[team00_30_aura_mixi_max_detail_info]],
    576015315 --[[team00_30_aura_soul_detail_info]], 3635526425 --[[team00_30_aura_kizuna_trans_detail_info]],
    1305553269 --[[team00_30_aura_awakening_power_detail_info]], 3131422953 --[[team00_30_aura_mode_change_detail_info]],
    26273556 --[[team00_30_p1_balloon]], 1921826160 --[[team00_40_change_page_guide]]},
  MAX_WAIT = 90,
  ready = false, frames = 0, open_at = nil, held = {}, fills = 0}
local DetailWaitLog = VRFW.logger.new("skill_slots detail gate")
-- Holds the details after a fill while the list is not open yet.
local function DetailWaitHold()
  if DetailWait.ready then
    return
  end
  DetailWait.fills = DetailWait.fills + 1
  DetailWait.held = {}
  for _, L in ipairs(DetailWait.LAYERS) do
    if funcLuaMenuCommand(262659071, L)
        and funcLuaMenuCommand(1262717583, L, 0) == true then
      DetailWait.held[L] = true
      funcLuaMenuCommand(711242136, L, 0, false)
    end
  end
end
local function DetailWaitStep()
  if DetailWait.ready then
    return
  end
  DetailWait.frames = DetailWait.frames + 1
  if not ((DetailWait.open_at ~= nil and DetailWait.frames > DetailWait.open_at) or DetailWait.frames >= DetailWait.MAX_WAIT) then
    return
  end
  DetailWait.ready = true
  local shown = 0
  for L in pairs(DetailWait.held) do
    funcLuaMenuCommand(711242136, L, 0, true)
    shown = shown + 1
  end
  DetailWait.held = {}
  DetailWaitLog("released at frame", DetailWait.frames, "list opened at", tostring(DetailWait.open_at), "fills held",
    DetailWait.fills, "layers shown", shown)
end
local DetailWaitRetailOnOpenLayer = OnOpenLayer
