    return DetailWaitRetailOnOpenLayer(a1, a2)
  end
  if a1 == List and DetailWait.open_at == nil then
    DetailWait.open_at = DetailWait.frames
  end
  return DetailWaitRetailOnOpenLayer(a1, a2)
end
