function UpdateSkillDetailWindow(a1, a2, a3)
  if CharacterReforged.SKILL_SLOTS_PICK_GEN ~= PICK_GEN then -- an earlier copy of this block: pass through (see the top)
    return RetailUpdateSkillDetailWindow(a1, a2, a3)
  end
  Mark(Bit.DETAIL)
  RetailUpdateSkillDetailWindow(a1, a2, a3)
  local okInfo = funcLuaCommand(2580586398, a1, 9)
  ListState.focus = (okInfo and type(a1) == "number") and a1 or 0
  local skill = to_u32(a1)
  if character_reforged_pick and skill == Miximax.CREATE then
    local card = CreateCard()
    local okc, done = false, false
    if card ~= nil then
      okc, done = pcall(card.detail, skill)
    end
    if not (okc and done) then
      pcall(MiximaxDetail)
    end
  elseif character_reforged_pick and skill == Miximax.FUSION then
    funcLuaMenuCommand(711242136, 3679282495 --[[the miximax window]], 0, false)   -- the hidden carrier: no detail
  end
  pcall(DetailWaitHold)
end
local RetailStep = Step
function Step()
  if CharacterReforged.SKILL_SLOTS_PICK_GEN ~= PICK_GEN then -- an earlier copy of this block: pass through (see the top)
    return RetailStep()
  end
  if RetailStep ~= nil then
    RetailStep()
  end
  pcall(DetailWaitStep)
  if VRFW.face_icon ~= nil and VRFW.face_icon.pending() then
    VRFW.face_icon.settle()                        -- the miximax portrait shown once its face loaded
  end
  ListState.frame = ListState.frame + 1
  if not character_reforged_pick then
    return
  end
  Mark(Bit.STEP)
  character_reforged_frames = character_reforged_frames + 1
  local blocked = ListState.input_blocked()   -- a popup is open, or its closing press is still down
  if character_reforged_frames == 2 and character_reforged_mode == "S" then
    pcall(function()
      funcLuaMenuCommand(2253672176, 1361375778 --[[sort]], 8, List)
      funcLuaMenuCommand(4114514990, List, true)
      funcLuaMenuCommand(306610847, List, 0)
      funcLuaMenuCommand(1778826357, Item, 0, true)
    end)
    pcall(funcLuaCommand, 519897777, "skill_slots", "hiper picker sort", 8,
      "create owned", funcLuaCommand(2011560392, Miximax.CREATE))
  end
  if character_reforged_frames < 10 then   -- ignore the Enter/click that opened the list on the slot screen
    return
  end
  local focus = to_u32(FocusedSkill())
  if focus == character_reforged_last_focus then
    character_reforged_stable = character_reforged_stable + 1
  else
    character_reforged_last_focus, character_reforged_stable = focus, 0
  end
  if blocked then
    return
  end
  if focus == Miximax.FUSION and not funcLuaCommand(4265778440, MENU_CTRL, COMMAND_ENTER)
      and not funcLuaCommand(4265778440, MENU_CTRL, COMMAND_ENTER_CLICK)
      and funcLuaCommand(4265778440, MENU_CTRL, 3421673595 --[[CMD_FUNC3]]) then
    PlayerSet(Miximax.KEY_DEL, 1)                 -- Eliminar on the fusion entry: undo it (the slot screen does it)
    PlayerSet(KEY_RESULT, focus)
    PlayerSet(KEY_INV, character_reforged_inv[focus] or 0)
    funcLuaCommand(1917805374, 2339718859 --[[sy0011]])
    character_reforged_pick = false
    funcLuaCommand(320421347, 2897322950 --[[ability_list_menu]])
    return
  end
  if funcLuaCommand(4265778440, MENU_CTRL, COMMAND_ENTER) then
    Mark(Bit.ENTER)
    PickEntry("Step-Enter", List, 0)
  elseif funcLuaCommand(4265778440, MENU_CTRL, COMMAND_ENTER_CLICK) then
    Mark(Bit.CLICK)
    local inside, instance = ListState.pointer_on_focused_row()
    if inside == true then
      ListState.focus_row_skill(instance)
      PickEntry("Step-Click", List, 0)
    elseif inside == nil and character_reforged_stable >= 2 then
      PickEntry("Step-Click", List, 0)
    end
  end
end

