local RetailUpdateButtonGuide = UpdateButtonGuide
local Guide = 1138543975                 -- mainmenu01_06_base_button_guide
local GUIDE_TEXTS = 2209673388
local GUIDE_KEYS = 452337289             -- (menu, guide, commands)
local FILTER_TEXTS = {[2493238543] = true, [773924788] = true}   -- the retail filter entry (on / off)
function UpdateButtonGuide()
  if CharacterReforged.SKILL_SLOTS_PICK_GEN ~= PICK_GEN then -- an earlier copy of this block: pass through (see the top)
    return RetailUpdateButtonGuide()
  end
  if not character_reforged_pick then
    return RetailUpdateButtonGuide()
  end
  -- The picker shows it.
  local retail_command = funcLuaMenuCommand
  local at = nil
  funcLuaMenuCommand = function(command, menu, layer, a, b, c, d, e, ...)
    if command == GUIDE_TEXTS and layer == Guide and type(a) == "table" then
      at = (FILTER_TEXTS[a[1]] and 2) or 1
      local entry = {3790324331, 2750714971, 0, 0, 0}
      for k, list in ipairs({a, b, c, d, e}) do
        if type(list) == "table" then
          table.insert(list, at, entry[k])
        end
      end
    elseif command == GUIDE_KEYS and layer == Guide and type(a) == "table" and at ~= nil then
      table.insert(a, at, 1981080283 --[[CMD_ENTER]])
    end
    return retail_command(command, menu, layer, a, b, c, d, e, ...)
  end
  local ok, err = pcall(RetailUpdateButtonGuide)
  funcLuaMenuCommand = retail_command
  if not ok then
    PRINT("ability_list_menu EVT pick guide: " .. tostring(err))
  end
end

